class Solution {public int[] solve(int n,int[][] edges){ArrayList<ArrayList<Integer>>reverse=new ArrayList<>();for(int i=0;i<n;i++)reverse.add(new ArrayList<>());int[] degree=new int[n];for(int[]e:edges){reverse.get(e[1]).add(e[0]);degree[e[0]]++;}ArrayList<Integer>q=new ArrayList<>();for(int i=0;i<n;i++)if(degree[i]==0)q.add(i);for(int i=0;i<q.size();i++)for(int u:reverse.get(q.get(i)))if(--degree[u]==0)q.add(u);Collections.sort(q);return q.stream().mapToInt(Integer::intValue).toArray();}}